// ---- Public read-only page: latest approved pulse + explainer + status of every week ----
const runs = $('Read runs').all(0, 0).map(i => i.json).filter(r => /^\d{4}-W\d{2}$/.test(String(r.run_id)));
let want = '';
try { want = String($('Webhook').first().json.query?.week || '').trim(); } catch (e) {}
const published = runs.filter(r => r.status === 'published').sort((a, b) => String(b.run_id).localeCompare(String(a.run_id)));
const run = published.find(r => r.run_id === want) || published[0];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const inline = s => esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/\*(.+?)\*/g, '<i>$1</i>')
  .replace(/\[(.+?)\]\((https?:\/\/[^)\s]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
const md = text => { const out = []; let list = null; const close = () => { if (list) { out.push(`</${list}>`); list = null; } };
  for (const line of String(text || '').split('\n')) { let m;
    if ((m = line.match(/^(#{1,3})\s+(.*)/))) { close(); out.push(`<h${m[1].length + 1}>${inline(m[2])}</h${m[1].length + 1}>`); }
    else if ((m = line.match(/^\d+\.\s+(.*)/))) { if (list !== 'ol') { close(); out.push('<ol>'); list = 'ol'; } out.push(`<li>${inline(m[1])}`); }
    else if ((m = line.match(/^\s+(\*Metric:\*.*)/))) { out.push(`<div class="metric">${inline(m[1])}</div></li>`); }
    else if ((m = line.match(/^-\s+(.*)/))) { if (list !== 'ul') { close(); out.push('<ul>'); list = 'ul'; } out.push(`<li>${inline(m[1])}</li>`); }
    else if (!line.trim()) close(); else { close(); out.push(`<p>${inline(line)}</p>`); } }
  close(); return out.join('\n'); };
const fmt = s => { const d = new Date(String(s).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? esc(s) : d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }); };
const THEME = { QUALITY: 'Answer quality', LIMITS: 'Usage limits', BUGS: 'App bugs', BILLING: 'Billing', PRAISE: 'Praise' };
const LABEL = { published: 'Published', awaiting_approval: 'Waiting for approval', approved: 'Approved, publishing', draft_ready: 'Draft ready',
  analysed: 'Analysed', processing: 'Processing', tagging_in_progress: 'Tagging', blocked: 'Blocked', rejected: 'Rejected',
  expired: 'Expired', publish_failed: 'Publish failed', draft_failed: 'Draft failed' };

let body;
if (!run) body = '<p class="empty">No approved pulse yet. The first one appears here after it is approved.</p>';
else {
  let exp = {}, rep = {};
  try { exp = JSON.parse(run.explainer_json || '{}'); } catch (e) {}
  try { rep = JSON.parse(run.validation_report || '{}'); } catch (e) {}
  const checks = rep.checks || {};
  const badge = (ok, t) => `<span class="chip ${ok ? 'ok' : 'warn'}">${ok ? '✓' : '!'} ${esc(t)}</span>`;
  body = `
<section class="card">
  <div class="meta">${esc(run.run_id)} · week ${fmt(run.week_start)} – ${fmt(run.week_end)} · approved ${esc(String(run.approved_at || '').replace(/:\d{2}$/, ''))} IST</div>
  <div class="chips">${badge(rep.passed, 'Validation passed')}${badge(Number(rep.pulse_words) <= 250, `${rep.pulse_words} words (≤250)`)}${badge(checks.quotes_verbatim, 'Quotes verbatim')}${badge(checks.numbers_from_stats, 'Numbers from computed stats')}${badge(true, 'Human-approved')}</div>
  <div class="pulse">${md(run.weekly_pulse)}</div>
</section>
<section class="card">
  <h2>Support snippet: "I paid ₹399 but the app still shows Free"</h2>
  <p class="sub">Fee issue <b>${esc(run.fee_code)}</b> · ${esc(run.fee_count)} reviews in 10 weeks · ${esc(String(run.fee_trend || '').split(',').pop().trim())}</p>
  ${md(exp.markdown)}
</section>`;
}
const rows = runs.sort((a, b) => String(b.run_id).localeCompare(String(a.run_id))).map(r => `<tr>
  <td>${r.status === 'published' ? `<a href="?week=${esc(r.run_id)}">${esc(r.run_id)}</a>` : esc(r.run_id)}</td><td>${fmt(r.week_start)} – ${fmt(r.week_end)}</td>
  <td><span class="st st-${esc(r.status)}">${esc(LABEL[r.status] || r.status)}</span></td><td>${esc(String(r.top_themes || '').split(',').filter(Boolean).map(t => THEME[t] || t).join(', ') || '–')}</td>
  <td>${r.fee_count ? esc(r.fee_count) + ' · ' + esc(String(r.fee_trend || '').split(',').pop().trim()) : '–'}</td></tr>`).join('');

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Review Pulse · ChatGPT Android (India)</title><style>
:root{--bg:#f6f5f2;--card:#fff;--ink:#1d1d1b;--mute:#6b6a66;--line:#e4e2dc;--acc:#0f6e5c;--warn:#a15c00}
@media (prefers-color-scheme:dark){:root{--bg:#161615;--card:#20201e;--ink:#ecebe7;--mute:#a3a29c;--line:#34332f;--acc:#5cc4ae;--warn:#e0a24a}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
.wrap{max-width:860px;margin:0 auto;padding:28px 16px 48px}header h1{font-size:26px;margin:0 0 4px}header p{margin:0;color:var(--mute)}
.flow{display:flex;flex-wrap:wrap;gap:6px;margin:18px 0 22px;font-size:13px}.flow span{background:var(--card);border:1px solid var(--line);border-radius:999px;padding:4px 10px}
.flow .gate{border-color:var(--acc);color:var(--acc);font-weight:600}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px 22px;margin-bottom:18px}
.meta,.sub{color:var(--mute);font-size:13px}.chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 4px}
.chip{font-size:12px;border-radius:6px;padding:2px 8px;border:1px solid var(--line)}.chip.ok{color:var(--acc)}.chip.warn{color:var(--warn)}
h2{font-size:20px;margin:18px 0 8px}h3{font-size:16px;margin:18px 0 6px}h4{font-size:15px}.metric{color:var(--mute);font-size:13px}
a{color:var(--acc)}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:8px 6px;border-bottom:1px solid var(--line);vertical-align:top}
th{color:var(--mute);font-weight:600}.st{white-space:nowrap}.st-published{color:var(--acc);font-weight:600}.st-blocked,.st-publish_failed,.st-draft_failed{color:var(--warn)}
.tbl{overflow-x:auto}footer{color:var(--mute);font-size:12px;margin-top:20px}.empty{color:var(--mute)}
</style></head><body><div class="wrap">
<header><h1>Review Pulse</h1><p>Weekly product pulse and fee explainer for ChatGPT Android (India), built from Google Play reviews by an AI agent. Published only after human approval.</p></header>
<div class="flow"><span>Mon 07:00 · collect reviews</span><span>Claude tags themes</span><span>code computes stats</span><span>Claude drafts + validator</span><span class="gate">Human approval</span><span>MCP → Google Doc + Gmail draft</span><span>this page</span></div>
${body}
<section class="card"><h2>Every week</h2><div class="tbl"><table><thead><tr><th>Week</th><th>Dates</th><th>Status</th><th>Top themes</th><th>Fee issue</th></tr></thead><tbody>${rows || '<tr><td colspan="5">No runs yet</td></tr>'}</tbody></table></div></section>
<footer>Live from the Review Pulse database · page generated ${new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 16).replace('T', ' ')} IST · read-only</footer>
</div></body></html>`;
return [{ json: { html } }];
